// level_data.dart
//
// חולץ אוטומטית מתוך logo_level_screen.dart - אותם levelsCounts + gameLevels
// בדיוק, בלי שינוי אף ערך, רק הועברו לקובץ נפרד כדי ש-duel_lobby_screen.dart
// ו-duel_room_screen.dart יוכלו להשתמש באותם לוגואים בלי תלות מעגלית
// בקובץ המסך המלא.
//
// ⚠️ פעולה נדרשת ב-logo_level_screen.dart:
// 1) למחוק משם את class LevelData + את levelsCounts + gameLevels
//    (בדיוק אותם הבלוקים שמופיעים כאן למטה)
// 2) להוסיף בראש הקובץ: import 'level_data.dart';
// 3) בתוך _LogoLevelScreenState, להשתמש ב-levelsCounts/gameLevels
//    הגלובליים האלה (כבר מיובאים) במקום בשדות ה-instance שנמחקו -
//    שאר הקוד לא צריך להשתנות כי השמות זהים.

import 'package:flutter/material.dart';

class LevelData {
  final String answer;
  final String imagePath;
  final Color logoColor;
  final List<String> keyboard;
  final String? ansEn;
  final List<String>? keyboardEn;

  LevelData({
    required String ans,
    required this.imagePath,
    required this.logoColor,
    required this.keyboard,
    this.ansEn,
    this.keyboardEn,
  }) : answer = ans.trim();

  // שולף את התשובה בשפה הנכונה בזמן ריצה - עברית כברירת מחדל,
  // ונופל חזרה לעברית אם אין תרגום אנגלי (ansEn == null) כדי שלא יקרוס.
  String answerFor(bool hebrew) => (hebrew || ansEn == null) ? answer : ansEn!;

  // כמו answerFor, אבל עבור מקלדת האותיות המוצגת למשתמש.
  List<String> keyboardFor(bool hebrew) =>
      (hebrew || keyboardEn == null) ? keyboard : keyboardEn!;
}

  final Map<int, int> levelsCounts = {
    1: 35,
    2: 33,
    3: 23,
    4: 33,
    5: 19,
    6: 28,
    7: 31,
    8: 29,
    9: 27,
