    21: 3, // כדורסל אירופי - קבוצות יורוליג מוכרות, אך פחות מ-NBA לקהל הישראלי
    22: 4, // NFL - פוטבול אמריקאי, נישתי יחסית לקהל הישראלי
    23: 3, // קבוצות כדורגל ישראליות - מערבב קבוצות מוכרות מליגת העל עם קבוצות ליגה לאומית פחות מוכרות
